def lexicographically_smallest_string(N, K, S):
    # The lexicographically smallest string can be achieved by sorting the first K characters
    # and using the sorted characters for the first K characters of each subsequence.
    # For the remaining characters, they can be placed in the subsequences as they are.
    sorted_first_k = sorted(S[:K])
    if K < N:
        # If K is less than N, the remaining characters will be part of the subsequences.
        # We need to compare the remaining characters with the first character of the sorted first K.
        first_char_of_sorted_k = sorted_first_k[0]
        for i in range(K, N):
            if S[i] < first_char_of_sorted_k:
                # If the current character is less than the first character of the sorted first K,
                # we should use it for the current subsequence.
                sorted_first_k = sorted(S[:i+1]) + sorted_first_k[1:]
                break
            elif S[i] > first_char_of_sorted_k:
                # If the current character is greater than the first character of the sorted first K,
                # we can use the sorted first K for all subsequences.
                break

    return ''.join(sorted_first_k)

def main():
    T = int(input().strip())
    results = []
    for _ in range(T):
        N, K = map(int, input().strip().split())
        S = input().strip()
        results.append(lexicographically_smallest_string(N, K, S))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
